<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { Search, Menu, X, ArrowLeft, ArrowRight, BookOpen, Timer, CheckCircle2, ChevronLeft, LayoutGrid, FileQuestion, RotateCcw } from 'lucide-vue-next';
import { gsap } from 'gsap';
import ServerExams from './ServerExams.vue';
import { organizations as initialOrganizations, questions } from './data';
const liveContent=!!import.meta.env.VITE_CONTENT_API;
const organizations=ref(liveContent?[]:initialOrganizations), catalogError=ref('');
function logoUrl(o){return o.logo_url||`/images/${o.logo||'dgapr.png'}`;}
const menu=ref(false), query=ref(''), activeQuery=ref(''), route=ref(location.hash), mode=ref('practice'), index=ref(0), answers=ref({}), revealed=ref(false), finished=ref(false), remaining=ref(300), running=ref(false);
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f\u064B-\u065F]/g,'').replace(/[أإآ]/g,'ا').trim().toLowerCase();
const filtered=computed(()=>organizations.value.filter(o=>normalize(o.name+' '+o.aliases).includes(normalize(activeQuery.value))));
const parts=computed(()=>route.value.replace('#/','').split('/'));
const organization=computed(()=>organizations.value.find(o=>o.id===parts.value[1]));
const isQuiz=computed(()=>parts.value[0]==='quiz' && organization.value);
const specialty=computed(()=>organization.value?.specialties.find(s=>s.id===parts.value[2]));
const question=computed(()=>questions[index.value]);
const score=computed(()=>questions.filter((q,i)=>answers.value[i]===q.correct).length);
const time=computed(()=>`${Math.floor(remaining.value/60).toString().padStart(2,'0')}:${(remaining.value%60).toString().padStart(2,'0')}`);
const answered=computed(()=>Object.keys(answers.value).length);
let tick, deadline=0;
function navigate(path){location.hash=path;menu.value=false;}
function focusMain(){document.getElementById('main')?.focus();}
function sync(){route.value=location.hash;running.value=!!(isQuiz.value && mode.value==='exam' && !finished.value);menu.value=false;nextTick(()=>{window.scrollTo(0,0);document.querySelector('main')?.focus();});}
function search(){activeQuery.value=query.value;if(parts.value[0])navigate('/');nextTick(()=>document.getElementById('organizations')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));}
function start(kind){mode.value=kind;index.value=0;answers.value={};revealed.value=false;finished.value=false;remaining.value=300;deadline=Date.now()+300000;navigate(`/quiz/${organization.value.id}/${specialty.value?.id||'surveillant'}`);nextTick(()=>{running.value=kind==='exam';});}
function choose(a){if(mode.value==='practice'&&revealed.value)return;answers.value={...answers.value,[index.value]:a};}
function finish(){finished.value=true;running.value=false;}
function next(){if(index.value<questions.length-1){index.value++;revealed.value=false;}else finish();}
onMounted(async()=>{window.addEventListener('hashchange',sync);tick=setInterval(()=>{if(running.value&&!finished.value){remaining.value=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(remaining.value<=0)finish();}},1000);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.from('.hero-copy',{y:15,opacity:0,duration:.7,clearProps:'all'});if(import.meta.env.VITE_CATALOG_API){try {const response=await fetch(import.meta.env.VITE_CATALOG_API,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('catalog');const catalog=await response.json();if(!Array.isArray(catalog)||catalog.some(o=>!o.id||!o.name||!Array.isArray(o.specialties)))throw new Error('catalog');organizations.value=catalog;}catch{catalogError.value=liveContent?'تعذّر تحميل الجهات. أعد المحاولة بعد التحقق من الاتصال.':'تعذّر تحميل الجهات. تظهر حالياً بيانات النسخة التجريبية.';}}});
onUnmounted(()=>{clearInterval(tick);window.removeEventListener('hashchange',sync);});
</script>

<template>
 <a class="skip" href="#main" @click.prevent="focusMain">انتقل إلى المحتوى</a>
 <header><div class="wrap header-inner"><a class="brand" href="#/" aria-label="التحضير لمباريات التوظيف — الرئيسية"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><span>التحضير لمباريات<br><strong>التوظيف</strong></span></a><button class="menu-toggle icon-button" @click="menu=!menu" :aria-expanded="menu" aria-controls="navigation" :aria-label="menu?'إغلاق القائمة':'فتح القائمة'"><X v-if="menu"/><Menu v-else/></button><nav id="navigation" :class="{open:menu}" aria-label="التنقل الرئيسي"><a href="#/" @click="menu=false">الرئيسية</a><a href="#/" @click="menu=false;nextTick(()=>document.getElementById('organizations')?.scrollIntoView())">الجهات والتخصصات</a><a href="#/guide">دليل التحضير</a></nav><span class="header-note">تعلّم. تدرّب. تقدّم.</span></div></header>
 <main id="main" tabindex="-1">
 <p v-if="catalogError" class="notice wrap" role="alert">{{catalogError}}</p>
 <template v-if="!parts[0]">
 <section class="hero wrap" aria-labelledby="hero-title"><div class="hero-copy"><span class="eyebrow">فضاؤك للتحضير للمباريات</span><h1 id="hero-title">استعد للمباراة<br>بخطوات واضحة.</h1><span class="accent"></span><p>اختر الجهة والتخصص، وتدرّب بثقة على امتحانك القادم.</p></div><form class="search" @submit.prevent="search"><label class="sr-only" for="organization-search">ابحث عن جهة أو مؤسسة</label><Search aria-hidden="true"/><input id="organization-search" v-model="query" placeholder="ابحث عن جهة أو مؤسسة" type="search"><button type="submit">بحث <ArrowLeft :size="19"/></button></form></section>
 <section id="organizations" class="wrap organizations" aria-labelledby="org-title"><div class="org-main"><div class="section-heading"><div><span class="kicker">الجهات والتخصصات</span><h2 id="org-title">لأي مباراة تستعد؟</h2><p>اختر الجهة للاطلاع على الدرجات والتخصصات.</p></div><LayoutGrid aria-hidden="true"/></div><p v-if="activeQuery" class="search-summary" role="status">{{ filtered.length }} نتيجة لـ «{{ activeQuery }}» <button class="text-button" @click="query='';activeQuery=''">عرض الكل</button></p><div class="org-grid"><a v-for="o in filtered" :key="o.id" class="org-card" :href="`#/organization/${o.id}`"><div class="logo-box"><img :src="logoUrl(o)" :alt="`شعار ${o.name}`" loading="lazy"></div><h3>{{o.name}}</h3><p>تدريبات وامتحانات حسب التخصص</p><span class="card-action">عرض التخصصات <ArrowLeft :size="18"/></span></a></div><div v-if="!filtered.length" class="empty"><Search/><h3>لم نجد جهة بهذا الاسم</h3><p>جرّب «العدل»، «السجون» أو «الأمن الوطني».</p><button class="button" @click="query='';activeQuery=''">عرض جميع الجهات</button></div></div><aside class="steps"><BookOpen :size="36"/><h2>كيف تبدأ؟</h2><ol><li><b>1</b><div><h3>اختر الجهة</h3><p>ابحث عن الجهة التي ترغب في اجتياز مباراتها.</p></div></li><li><b>2</b><div><h3>حدّد التخصص</h3><p>اطّلع على الدرجات والتخصصات المتاحة.</p></div></li><li><b>3</b><div><h3>تدرّب واختبر مستواك</h3><p>تعلّم من التصحيح وراجع نقاط ضعفك.</p></div></li></ol></aside></section>
 <section class="modes"><div class="wrap"><div class="center-heading"><span class="kicker">بطريقتك، وعلى إيقاعك</span><h2>اختر طريقة التحضير المناسبة لك</h2><p>ابدأ بالتدريب، ثم اختبر ما تعلّمته.</p></div><div class="mode-grid"><article class="mode-card"><FileQuestion :size="48"/><h3>تدريب مع التصحيح</h3><p>تدرّب حسب تخصصك، وافهم الإجابة خطوة بخطوة.</p><a class="button" href="#/" @click="nextTick(()=>document.getElementById('organizations')?.scrollIntoView())">اختر الجهة والتخصص <ArrowLeft :size="18"/></a></article><article class="mode-card dark"><Timer :size="48"/><h3>امتحان تجريبي بالتوقيت</h3><p>اختبر مستواك، ثم راجع نتيجتك وتصحيح إجاباتك.</p><a class="button yellow" href="#/" @click="nextTick(()=>document.getElementById('organizations')?.scrollIntoView())">اختر امتحانك <ArrowLeft :size="18"/></a></article></div></div></section>
 <section class="wrap faq"><div class="center-heading"><h2>أسئلة شائعة</h2><p>كل ما تحتاجه لبدء التحضير.</p></div><details open><summary>كيف أبدأ التحضير؟</summary><p>اختر الجهة، ثم الدرجة أو التخصص، وابدأ التدريب أو الامتحان التجريبي.</p></details><details><summary>ما الفرق بين التدريب والامتحان التجريبي؟</summary><p>التدريب يتيح تصحيح كل إجابة مباشرة، بينما تظهر نتيجة الامتحان وتصحيحه بعد التسليم أو انتهاء الوقت.</p></details><details><summary>هل هذه الأسئلة رسمية؟</summary><p>الأسئلة الحالية أمثلة تعليمية عامة، وليست مواضيع رسمية أو توقعاً لأسئلة المباراة.</p></details><div class="callout"><div><h2>ابدأ بخطوة، واستعد بثقة.</h2><p>اختر الجهة التي تهمك، وابدأ مشوار التحضير.</p></div><a href="#/" class="button" @click="nextTick(()=>document.getElementById('organizations')?.scrollIntoView())">استكشف الجهات <ArrowLeft :size="18"/></a></div></section>
 </template>
 <section v-else-if="parts[0]==='organization' && organization" class="wrap inner-page"><a href="#/" class="back"><ArrowRight :size="18"/> جميع الجهات</a><div class="org-page-title"><img :src="logoUrl(organization)" :alt="`شعار ${organization.name}`"><div><span class="kicker">اختر الدرجة أو التخصص</span><h1>{{organization.name}}</h1></div></div><p class="notice">تُضاف التخصصات والمحتويات تدريجياً. النموذج المتاح حالياً توضيحي.</p><a v-for="s in organization.specialties" :key="s.id" class="specialty" :href="`#/specialty/${organization.id}/${s.id}`"><FileQuestion/><div><h2>{{s.name}}</h2><p>نموذج توضيحي • تدريب عام مع التصحيح</p></div><ChevronLeft/></a><div v-if="!organization.specialties.length" class="empty"><BookOpen :size="42"/><h2>التخصصات قيد الإعداد</h2><p>لم تُضف بعد تخصصات لهذه الجهة.</p><a class="button" href="#/">العودة إلى الجهات</a></div></section>
 <section v-else-if="parts[0]==='specialty' && specialty" class="wrap inner-page"><a :href="`#/organization/${organization.id}`" class="back"><ArrowRight :size="18"/> تخصصات الجهة</a><span class="kicker">{{organization.name}}</span><h1>{{specialty.name}}</h1><ServerExams v-if="liveContent && specialty.database_id" :key="specialty.database_id" :specialty="specialty"/><template v-else><p class="notice">مثال توضيحي: خمسة أسئلة تعليمية عامة، وليست نموذجاً رسمياً لهذه المباراة.</p><div class="mode-grid"><article class="mode-card"><BookOpen :size="42"/><h2>تدريب مع التصحيح</h2><p>خذ وقتك، وأظهر شرح كل إجابة قبل السؤال التالي.</p><button class="button" @click="start('practice')">ابدأ التدريب</button></article><article class="mode-card dark"><Timer :size="42"/><h2>امتحان تجريبي</h2><p>5 أسئلة • 5 دقائق • التصحيح بعد التسليم</p><button class="button yellow" @click="start('exam')">ابدأ الامتحان</button></article></div></template></section>
 <section v-else-if="isQuiz && specialty" class="wrap quiz-page"><a :href="`#/specialty/${organization.id}/${specialty.id}`" class="back"><ArrowRight :size="18"/> العودة إلى التخصص</a><template v-if="!finished"><div class="quiz-top"><span>{{mode==='exam'?'امتحان تجريبي':'تدريب مع التصحيح'}}</span><span v-if="mode==='exam'" class="clock" :class="{urgent:remaining<60}"><Timer :size="18"/> <span dir="ltr">{{time}}</span></span></div><progress :value="index+1" :max="questions.length" :aria-label="`السؤال ${index+1} من ${questions.length}`"></progress><p class="kicker">السؤال {{index+1}} من {{questions.length}}</p><h1 class="question">{{question.q}}</h1><fieldset><legend class="sr-only">اختر إجابة واحدة</legend><label v-for="(a,i) in question.a" :key="i" class="answer" :class="{selected:answers[index]===i,correct:revealed&&i===question.correct,wrong:revealed&&answers[index]===i&&i!==question.correct}"><input type="radio" :name="`question-${index}`" :checked="answers[index]===i" :disabled="revealed" @change="choose(i)"><span>{{a}}</span></label></fieldset><div v-if="revealed" class="explanation" role="status"><strong>{{answers[index]===question.correct?'إجابة صحيحة':'راجع الإجابة'}}</strong><p>{{question.why}}</p></div><div class="quiz-actions"><button v-if="mode==='practice'&&!revealed" class="button" :disabled="answers[index]===undefined" @click="revealed=true">تحقّق من الإجابة</button><button v-else class="button" @click="next">{{index===questions.length-1?'إنهاء وعرض النتيجة':'السؤال التالي'}} <ArrowLeft :size="18"/></button><button v-if="mode==='exam'" class="text-button" @click="finish">تسليم الامتحان ({{answered}}/{{questions.length}})</button></div><p class="muted">{{mode==='exam'?'يمكن تجاوز السؤال؛ تُحتسب الأسئلة دون إجابة ضمن الإجابات غير الصحيحة.':'النتيجة للتعلّم، وليست تقييماً رسمياً.'}}</p></template><template v-else><div class="result"><CheckCircle2 :size="48"/><h1>أنهيت {{mode==='exam'?'الامتحان':'التدريب'}}</h1><strong class="score">{{score}} / {{questions.length}}</strong><p>راجع الشروحات لتحديد ما تحتاج إلى مراجعته.</p></div><article v-for="(q,i) in questions" :key="i" class="review"><h2>{{i+1}}. {{q.q}}</h2><p>إجابتك: {{q.a[answers[i]]??'لم تُجب'}} <span>{{answers[i]===q.correct?'✓':'✕'}}</span></p><p><strong>الإجابة الصحيحة: {{q.a[q.correct]}}</strong></p><p>{{q.why}}</p></article><button class="button" @click="start(mode)"><RotateCcw :size="18"/> إعادة المحاولة</button></template></section>
 <section v-else-if="parts[0]==='guide'" class="wrap inner-page guide"><a class="back" href="#/">العودة إلى الرئيسية</a><h1>دليل التحضير</h1><article v-for="(text,i) in ['ابدأ بالإعلان الرسمي للمباراة وحدّد المواد والشروط الواردة فيه.','قسّم وقتك بين مراجعة المفاهيم، حل الأسئلة وتصحيح الأخطاء.','ابدأ بالتدريب دون توقيت، ثم انتقل إلى المحاكاة بالتوقيت.','دوّن الأخطاء المتكررة وراجع سبب كل إجابة قبل إعادة المحاولة.']" :key="i"><b>{{i+1}}</b><p>{{text}}</p></article></section>
 <section v-else class="wrap inner-page empty"><h1>الصفحة غير موجودة</h1><a href="#/" class="button">الرئيسية</a></section>
 </main>
 <footer><div class="wrap footer-grid"><div><h2>التحضير لمباريات التوظيف</h2><p>منصة مستقلة للتحضير لمباريات الوظيفة العمومية.</p></div><div><h3>روابط سريعة</h3><a href="#/">الجهات والتخصصات</a><a href="#/guide">دليل التحضير</a></div><div><h3>حول النسخة الحالية</h3><p>{{liveContent?'لا يلزم إنشاء حساب للتدريب. تُحفظ نتائج الامتحانات على الخادم دون بيانات شخصية.':'نسخة تجريبية. لا يلزم إنشاء حساب، ولا تُحفظ الإجابات بعد مغادرة الصفحة.'}}</p></div></div><p class="footer-bottom wrap">الأسئلة تدريبية وليست أسئلة رسمية للمباريات. شعارات الجهات للتعريف بها.</p></footer>
</template>

